// One-time seed of the claude-code-web-users-support pack into the EXISTING fleet's
// declarations, naming this fleet's preferences store.
//
// The pack carries what a project can offer people working from Claude Code on the
// WEB, where the session knows who they are — today, reading the current user's
// personal interaction preferences into their session from a repo its config names. New repos get the pack from
// `--init` (it flags `seededByDefault`) and the store from its adoption question;
// this record catches the repos bootstrapped before the pack existed, so today's
// sessions do not silently lose the preferences they had.
//
// It carries the STORE as a literal, which is the one thing a canon record may do
// that shared code may not: a migration record is a dated one-off whose purpose is
// to move a specific fleet off a specific old shape, and it stops shipping once it
// ages out of the vendoring window. Nothing standing is left naming
// `missingbulb/Sheepdog` — the durable path is the pack's adoption question (new
// repos) and the sheepdog pack's fleet-preferences sweep, which reads the store
// from the enforcer repo's own config and so serves any fleet.
//
// SEED, NEVER OVERRIDE (the `declarePacks` op's contract): a repo that already
// declares the pack keeps its entry, and one that already names a store keeps that
// store. Both are decisions this record must not relitigate.
//
// The ORDER this depends on: baselining applies migration notes after it vendors the
// mount, and re-converges the mount when this pass changed the declaration — because
// a declared pack whose code is absent is a blocking `config` error. Both halves land
// in the one transactional commit.
//
// legacyPresent: a member carries a declaration that does not declare the pack at
// all. A repo with no declaration is not a member and is not this record's business;
// a member that declares the pack and deliberately configured it otherwise has
// converged as far as this record is concerned.
export default {
  id: 'claude-code-web-users-support',
  landed: '2026-08-07',
  summary: 'seed the claude-code-web-users-support pack into existing members, naming the fleet\'s preferences repo',
  declarePacks: [{ id: 'claude-code-web-users-support', config: { repo: 'missingbulb/Sheepdog' } }],
  legacyPresent: async (exists, read) => {
    const raw = await read('.claudinite-checks.json');
    if (raw == null) return false;
    try {
      const { packs } = JSON.parse(raw);
      if (!Array.isArray(packs)) return false;
      return !packs.some((e) => (typeof e === 'string' ? e : e?.id) === 'claude-code-web-users-support');
    } catch {
      return false; // unparsable settings are the world runner's finding, not this record's
    }
  },
};

// The 2026-08-11 fleet-baseline conversion (#749): the sheepdog pack's manual lever
// over the fleet stopped being a standalone WORKFLOW (a managed copy in the enforcer's
// own .github/, the one file the nightly converge could never push — #649) and became
// an ordinary `manual`-frequency TASK (packs/sheepdog/tasks/fleet-baseline/) riding
// the vendored scheduler: Actions → Claudinite scheduler → Run workflow →
// `overrides: FORCE_TASKS=fleet-baseline`.
//
// Canon-side the conversion is complete — the stub the old record materialized
// (packs/sheepdog/stubs/workflows/fleet-baseline.yml) is deleted, which makes the
// 2026-08-05 sheepdog-fleet-baseline record's materialization a permanent no-op (a
// missing template is a skip, never a clobber; see applyMaterializations). What
// remains member-side is the COPY that record installed: an enforcer's own
// .github/workflows/fleet-baseline.yml, now orphaned — its `run:` step points at a
// mount path the vendor refresh no longer carries, so left in place it is a button
// that fails when pressed. Removing a workflow file needs the `workflows` permission
// the Action token does not hold, so the removal rides baselining's agent stage over
// MCP — the same lane that landed the file (#649), run in reverse.
const DECLARATION = '.claudinite-checks.json';
const PACK = 'sheepdog';

export default {
  id: 'fleet-baseline-task',
  landed: '2026-08-11',
  summary: 'fleet-baseline converted from a standalone workflow to a manual-frequency sheepdog task; the enforcer\'s .github/workflows/fleet-baseline.yml copy is retired',

  // Same gate as the record that installed the file: does this repo declare the
  // sheepdog pack. An unreadable declaration means "not an enforcer as far as this
  // record can tell" — skip, never guess.
  appliesTo: async (read) => {
    const text = await read(DECLARATION);
    if (!text) return false;
    let cfg;
    try { cfg = JSON.parse(text); } catch { return false; }
    return (Array.isArray(cfg?.packs) ? cfg.packs : [])
      .some((e) => (typeof e === 'string' ? e : e?.id) === PACK);
  },

  agentic: {
    model: 'haiku',
    instructions: 'If this repo has a tracked .github/workflows/fleet-baseline.yml, delete it (git rm) on the maintenance branch — the fleet-baseline lever is now the sheepdog pack\'s manual-frequency task (run the Claudinite scheduler workflow by hand with overrides FORCE_TASKS=fleet-baseline), and the old workflow points at mount paths the vendor refresh no longer carries, so it is a button that fails when pressed. Do not touch claudinite-scheduler.yml. A repo with no such file needs nothing.',
  },

  legacyPresent: async (exists) => exists('.github/workflows/fleet-baseline.yml'),
};

#!/usr/bin/env node
// Perform every declared migration's write side in a checkout:
//   - file aliases  — "prefer Y, fall back to X, and rename X -> Y"
//   - materialize   — vendor pack templates into the repo's own tree
//   - rewrite       — repoint refs in place (idempotent literal replacements)
//   - declarePacks  — declare a pack (and its config) the member does not carry yet
// Idempotent: a no-op once everything has been applied. Dependency-free.
//
// Two roots. The DEST is the repo being healed (CLAUDE_PROJECT_DIR / cwd). The
// TEMPLATE source is the canon that ships the migrations — the parent of this
// migrations/ dir: in the canon repo that's the repo root; in a consumer that
// mounts Claudinite at .claudinite/, it's .claudinite/ (so a template path like
// packs/…/stubs/foo.yml resolves against the mounted pack, while its dest lands
// in the consumer's own .github/). The two coincide in the canon repo.
//
// Runs against a local checkout (a session, CI, or a future SessionStart
// self-heal hook wired via bootstrap). Each member migrates ITSELF: baselining
// runs this applier from the fresh canon clone it fetched, so even a dormant
// project catches up on every record ever landed — there is no fleet-wide
// apply pass and no retirement; the records simply accumulate.
import { existsSync, renameSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { loadMigrations, applyFileAliases, applyMaterializations, applyRewrites, applyPackDeclarations } from './registry.mjs';

async function main() {
  const repoRoot = process.env.CLAUDE_PROJECT_DIR || process.cwd();
  const canonRoot = dirname(dirname(fileURLToPath(import.meta.url))); // parent of migrations/
  const migrations = await loadMigrations();

  const exists = (p) => existsSync(join(repoRoot, p));
  const read = (p) => (existsSync(join(repoRoot, p)) ? readFileSync(join(repoRoot, p), 'utf8') : null);
  const write = (p, c) => {
    mkdirSync(dirname(join(repoRoot, p)), { recursive: true });
    writeFileSync(join(repoRoot, p), c);
  };
  const move = (from, to) => {
    mkdirSync(dirname(join(repoRoot, to)), { recursive: true });
    renameSync(join(repoRoot, from), join(repoRoot, to));
  };
  const readTemplate = (p) => (existsSync(join(canonRoot, p)) ? readFileSync(join(canonRoot, p), 'utf8') : null);

  const applied = [];
  for (const m of migrations) {
    applied.push(...(await applyFileAliases(m, { exists, move })));
    applied.push(...(await applyMaterializations(m, { readTemplate, read, write })));
    applied.push(...(await applyRewrites(m, { read, write })));
    applied.push(...(await applyPackDeclarations(m, { read, write })));
  }
  if (applied.length) console.log(`Applied migrations:\n${applied.map((x) => `  ${x}`).join('\n')}`);
}

const isMain = process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href;
if (isMain) {
  main().catch((e) => { console.error(`migrations apply failed: ${e.message}`); process.exit(1); });
}

#!/usr/bin/env node
// World-scope conformance runner (see DESIGN.md): the rules that audit repo
// state as it exists now, plus the pack-agnostic settings/load integrity
// diagnostics (malformed config, an unknown pack, a broken pack.mjs). Rules that
// judge the current change (`scope: 'work'`) run in check_the_work.mjs, which
// this file shares no code with — only the scope-blind mechanism helpers
// (run-active-pack-rules.mjs, report-findings.mjs). It names NO pack: adoption
// interview hygiene is a skill-owned check that rides its own pack's activation,
// and a malformed `questions` field is a load fault the pack registry reports.
// Wired into the project's test/CI flow, not the Stop hook. Dependency-free Node ≥18.
//   (default)   whole-repo sweep — milliseconds on a text corpus, sees cross-file breakage
//   --changed   transitional: scope to files changed vs the merge-base with main
//               (adopting a repo with a backlog only — not the enforcement default)
//   --base REF  override the base ref
//   --list      machine-readable catalog of every rule, both scopes (id, severity, description, doc)
//   --init      write .claudinite-checks.json — basics plus the fingerprinted packs
import { writeFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { buildContext } from './helpers/repo-context.mjs';
import { discoverPacks, resolveDeclaredPacks } from '../pack_loader/pack-registry.mjs';
import { runActivePackRules, packRules } from './run-active-pack-rules.mjs';
import { reportFindings } from './report-findings.mjs';

const configError = (what, fix) => ({
  rule: 'config', severity: 'blocking', file: '.claudinite-checks.json', line: null,
  what, why: 'the settings file is what executes — a bad key, value, or pack name silently changes what runs', fix, doc: 'engine/checks/README.md',
});

const args = process.argv.slice(2);
const has = (flag) => args.includes(flag);
const value = (flag) => (args.includes(flag) ? args[args.indexOf(flag) + 1] : null);
// The repo to sweep. `--root` first, then CLAUDE_PROJECT_DIR, and only then the cwd.
// The env var is not a convenience: the callers that run this from inside a converge
// (baselining's worker) have a cwd that no longer exists — the vendor step deletes
// `.claudinite/shared/`, which is where prework's cwd lives — and `process.cwd()` then
// throws `ENOENT … uv_cwd` before a single check runs, which reads from the outside as
// "this mount has no checks" (#689). engine/selftest.mjs has always resolved its root
// this way; this closes the disagreement for every caller, not just that one.
const root = value('--root') || process.env.CLAUDE_PROJECT_DIR || process.cwd();

if (has('--list')) {
  const { packs } = await discoverPacks({ localRoot: root });
  for (const r of packRules(packs)) {
    console.log(`${r.id}\t${r.severity}\t${r.description}\t${r.doc}`);
  }
  process.exit(0);
}

if (has('--init')) {
  const path = join(root, '.claudinite-checks.json');

  const path = join(root, '.claudinite-checks.json');
  if (existsSync(path)) {
    console.log(`${path} already exists — leaving it as-is.`);
    process.exit(0);
  }
  const { packs } = await discoverPacks({ localRoot: root });
  const ctx = buildContext({ root, mode: 'all' });
  // No pack is active by default, so the baseline is seeded as an explicit
  // declaration alongside the fingerprinted packs: every pack that flags
  // `seededByDefault` is written in (discovered structurally — the engine names
  // no pack), plus the ones a fingerprint detects. A seeded pack is still
  // opt-out-able where its own policy allows (baselining re-adds only the packs
  // whose absence it treats as drift), so removing a seeded declaration can
  // stick; each seeded pack ships its own one-time seed migration for the fleet.
  // Local packs are declared by hand, never fingerprinted or seeded — exclude
  // them from --init's seeding so a repo that already carries local packs (but
  // no config yet) doesn't auto-declare them.
  const seeded = packs.filter((p) => p.seededByDefault && !p.local).map((p) => p.id);
  const detected = [...seeded, ...packs.filter((p) => p.detect && !p.local && p.detect(ctx)).map((p) => p.id)];
  // A pack can't be imported without its dependencies — pull each declared pack's
  // `requires` closure into the declaration so it's complete and visible.
  const declared = resolveDeclaredPacks(detected, packs);
  // maintenance.delivery is deliberately materialized, not defaulted — the selection
  // must be visible in the file where a project would change it (see engine/checks/README.md).
  // Only what carries a decision: the declaration and the always-explicit
  // delivery. Empty rules/accept boilerplate is noise, not settings (#385);
  // loadConfig defaults absent keys.
  writeFileSync(path, `${JSON.stringify({ packs: declared, maintenance: { delivery: 'auto-merge' } }, null, 2)}\n`);
  console.log(`Wrote ${path} (packs: ${declared.join(', ')}).`);
  // The adoption interview (surfacing each declared pack's pending questions) is
  // driven by the adopt-claudinite skill / bootstrap.md, and nudged every session
  // by the SessionStart interview-check step — not printed here, so this runner
  // imports no pack.
  process.exit(0);
}

const { packs, errors: packErrors } = await discoverPacks({ localRoot: root });
const ctx = buildContext({ root, mode: has('--changed') ? 'changed' : 'all', baseOverride: value('--base') });

// Settings/load integrity — pack-agnostic, so the world runner owns them.
// Settings validity is checked at load: malformed JSON, an unknown
// property, and a wrong pack name are all equally settings errors. loadConfig
// reports the first two; the runner adds unknown pack names (only it holds the
// registry) and broken/duplicate local pack.mjs faults.
const findings = [];
for (const e of ctx.config.errors) findings.push(configError(e.what, e.fix));
for (const e of packErrors) findings.push(configError(e.what, e.fix));
// knownIds spans canon AND local packs, so a declared local pack id is valid and
// the unknown-pack message lists it among the declarable packs. ctx.config.packs
// is loadConfig's normalized view — bare ids, a namespaced local_packs/<name>
// declaration already resolved through packEntryId.
const knownIds = new Set(packs.map((p) => p.id));
for (const name of ctx.config.packs) {
  if (typeof name === 'string' && !knownIds.has(name)) {
    findings.push(configError(`declares unknown pack "${name}"`, `remove it or fix the name — declarable packs: ${[...knownIds].sort().join(', ')}`));
  }
}
// (Adoption-interview hygiene is a skill-owned check that runs below with the
// other active-pack rules; a malformed `questions` field arrives as a load fault
// in packErrors above. Neither names a pack here.)

// The world rules: everything not scoped to the work. A broken contributedRules
// seam is a config-level fault surfaced here (the world runner owns diagnostics).
findings.push(...runActivePackRules(ctx, packs, {
  includeRule: (rule) => rule.scope !== 'work',
  onContributeError: (pack, e) => findings.push(configError(
    `the "${pack.id}" pack's contributedRules failed: ${e.message}`, 'fix the pack manifest, or the contribution it interprets')),
}));

const blocking = reportFindings(findings, ctx.config, { scopeLabel: 'world', mode: ctx.mode, baseRef: ctx.baseRef });
process.exit(blocking ? 1 : 0);

// Scope-blind mechanism: apply the project's severity overrides and acceptances,
// order blocking-first, print each finding, and print the one-line summary.
// Returns the blocking count so a runner's exit code is `blocking ? 1 : 0`.
// `scopeLabel` only names the run in the summary line (e.g. "world" / "work") —
// this file carries no scope logic of its own.
import { applyConfig, render } from './helpers/findings.mjs';

export function reportFindings(findings, config, { scopeLabel, mode, baseRef }) {
  const resolved = applyConfig(findings, config)
    .sort((a, b) => (a.severity === b.severity ? 0 : a.severity === 'blocking' ? -1 : 1));
  for (const f of resolved) console.log(`${render(f)}\n`);
  const blocking = resolved.filter((f) => f.severity === 'blocking').length;
  const advisory = resolved.length - blocking;
  if (resolved.length) {
    console.log(`${blocking} blocking, ${advisory} advisory (${scopeLabel} scope: ${mode}${baseRef ? ` vs ${baseRef}` : ''}).`);
  }
  return blocking;
}

